export class Watcher {
  readonly events: WatchEvent[] = []; // the last 200
  readonly failing = new Set<string>();
  readonly seen = new Set<string>();
  flatFor = 0;

  onTool: HookCallback = async (input) => { // PostToolUse and PostToolUseFailure
    const ev = WatchEvent.of(input); // tool, normalized input hash, output hash, error signature, file hash
    this.events.push(ev);
    if (this.events.length > 200) this.events.shift();
    this.flatFor = this.progressed(ev) ? 0 : this.flatFor + 1;
    state.verdict = { flatFor: this.flatFor, loopKind: this.loopKind(ev), evidence: ev.evidence() };
    return {};
  };

  progressed(ev: WatchEvent): boolean {
    const fixed = ev.isCheck && ev.passed && this.failing.has(ev.check); // failed before, passes now
    if (ev.isCheck) this.failing[ev.passed ? "delete" : "add"](ev.check);
    const firstRead = ev.tool === "Read" && !this.seen.has(ev.file);
    if (ev.tool === "Read") this.seen.add(ev.file);
    return fixed || ev.todoCompleted || firstRead;
  }
}

loopKind(ev: WatchEvent): string | null {
  const last = this.events.slice(-6);
  if (ev.error) this.errors.set(ev.error, (this.errors.get(ev.error) ?? 0) + 1);
  const undo = this.rememberFile(ev); // an edit that brings a file back to an earlier hash
  if (last.length >= 3 && last.slice(-3).every((e) => e.key === ev.key)) return "same command, same result";
  if (ev.error && (this.errors.get(ev.error) ?? 0) >= 3) return "same error again";
  if (undo) return "undo and redo";
  const keys = (from: number) => new Set(last.filter((_, i) => i % 2 === from).map((e) => e.key));
  if (last.length === 6 && keys(0).size === 1 && keys(1).size === 1) return "ping-pong";
  return null;
}

const RUNGS = ["nudge", "replan", "think_harder", "fresh_start", "ask_person"] as const;
const STEP_IN_AT = [6, 9, 12, 15, 18]; // tool events with no real progress; tuned from logged verdicts

/** Rungs 1-2: extra context returned by the watcher's PostToolUse hook. */
export const inTurnContext = (v: WatcherVerdict): string | undefined => {
  if (v.flatFor === STEP_IN_AT[0]) return `Heads up: ${v.loopKind} (${v.evidence}). Try a different approach, or say what blocks you.`;
  if (v.flatFor === STEP_IN_AT[1]) return "Step back: write a short new plan for this step before you do anything else.";
  return undefined;
};

/** Rungs 3-5: at a step boundary, after a checkpoint. */
export const betweenTurns = async (run: Run, session: NovaSession, v: WatcherVerdict): Promise<void> => {
  if (v.flatFor === 0) { run.rung = 2; return; } // real progress resets the ladder
  const rung = RUNGS[run.rung];
  if (!rung || v.flatFor < STEP_IN_AT[run.rung]!) return;
  metrics.handoffs.add(1, { rung });
  if (rung === "think_harder") run.route = await rerunOneLevelUp(session, run.step, run.route);
  if (rung === "fresh_start") { await checkpoint(run, run.step); await run.restartSession({ seed: await run.notes() }); }
  if (rung === "ask_person") await askHuman(run, `I'm stuck on '${run.step.title}': ${v.summary()}. What should I try?`);
  run.rung += 1;
};

