// Recorded tool events from four runs on RH-1234, shortened. Each one is what a PostToolUse hook would see.
const test = (out, passed) => ({ tool: 'Bash', input: 'npm test -- ProjectsTable', output: out, check: 'ProjectsTable', passed });
const edit = (content) => ({ tool: 'Edit', input: 'src/ProjectsTable.tsx', file: 'src/ProjectsTable.tsx', content });
const read = (file) => ({ tool: 'Read', input: file, file });
const FAIL = 'FAIL expected "No projects yet", received ""';

export const SEQUENCES = {
  // Slow but healthy: read, test fails, edit, test fails differently, edit, test passes, next item.
  healthy: [
    read('src/ProjectsTable.tsx'), read('src/EmptyState.tsx'), test(FAIL, false), edit('v1'),
    test('FAIL expected 1 card, received 0', false), edit('v2'), test('PASS 12 tests', true),
    { tool: 'TodoWrite', input: 'empty card', todoCompleted: true }, read('src/ProjectsTable.test.tsx'),
    { tool: 'Bash', input: 'npm test -- Filter', output: 'FAIL expected "No results"', check: 'Filter', passed: false },
    edit('v3'), { tool: 'Bash', input: 'npm test -- Filter', output: 'PASS 4 tests', check: 'Filter', passed: true },
  ],
  // A test that times out, retried again and again with small edits that change nothing.
  flaky: Array.from({ length: 20 }, (_, i) => i % 2 === 0
    ? { tool: 'Bash', input: 'npm test -- ProjectsTable', output: `FAIL Timeout of ${5000 + i} ms exceeded`, check: 'ProjectsTable', passed: false,
        error: `Timeout of ${5000 + i} ms exceeded` }
    : read('src/ProjectsTable.tsx')),
  // An edit, then the opposite edit, then the first one again.
  undo: [read('src/ProjectsTable.tsx'), edit('with card'), test(FAIL, false), edit('without card'), test(FAIL, false), edit('with card'), test(FAIL, false)],
  // Two commands taking turns: A, B, A, B, A, B.
  pingpong: Array.from({ length: 6 }, (_, i) => i % 2 === 0
    ? { tool: 'Bash', input: 'git stash', output: 'Saved working directory' }
    : { tool: 'Bash', input: 'git stash pop', output: 'Dropped refs/stash@{0}' }),
};
