// The progress watcher: it looks for progress, not activity. No clocks, no turn counts.
import { createHash } from 'node:crypto';

const hash = (s) => createHash('sha256').update(String(s)).digest('hex').slice(0, 8);
const errorSignature = (e) => e?.split('\n')[0].replace(/\d+/g, 'N'); // first line, numbers masked

export class Watcher {
  events = [];
  errors = new Map();
  fileHashes = new Map();
  failing = new Set();
  seen = new Set();
  flatFor = 0;
  lastLoop = null;

  onTool(raw) { // the PostToolUse hook calls this with every tool call and its result
    const ev = { ...raw, key: `${raw.tool}:${hash(raw.input)}:${hash(raw.output ?? raw.content)}`, error: errorSignature(raw.error) };
    this.events.push(ev);
    if (this.events.length > 200) this.events.shift();
    const progressed = this.progressed(ev);
    this.flatFor = progressed ? 0 : this.flatFor + 1;
    const kind = this.loopKind(ev);
    this.lastLoop = progressed ? null : kind ?? this.lastLoop; // the last loop seen since real progress
    return { flatFor: this.flatFor, loopKind: this.lastLoop };
  }

  // Build it: real progress is a check that failed before and now passes, a plan item completed,
  // or a file read for the first time. For now every tool call counts, so activity looks like progress.
  progressed(ev) {
    return true;
  }

  loopKind(ev) {
    const last = this.events.slice(-6);
    if (ev.error) this.errors.set(ev.error, (this.errors.get(ev.error) ?? 0) + 1);
    const undo = this.rememberFile(ev);
    if (last.filter((e) => e.key === ev.key).length >= 3) return 'same command, same result';
    if (ev.error && this.errors.get(ev.error) >= 3) return 'same error again';
    if (undo) return 'undo and redo';
    const keys = (from) => new Set(last.filter((_, i) => i % 2 === from).map((e) => e.key));
    if (last.length === 6 && keys(0).size === 1 && keys(1).size === 1) return 'ping-pong';
    return null;
  }

  rememberFile(ev) { // true when an edit brings a file back to a state it had before
    if (ev.tool !== 'Edit') return false;
    const before = this.fileHashes.get(ev.file) ?? [];
    const h = hash(ev.content);
    this.fileHashes.set(ev.file, [...before, h]);
    return before.slice(0, -1).includes(h);
  }
}
