// The ladder: when progress stays flat, step in one rung at a time. Never stop a run for being slow.
export const RUNGS = [
  { at: 6, name: 'nudge', where: 'in the turn', say: (v) => `Heads up: ${v.loopKind ?? 'no progress'}. Try a different approach, or say what blocks you.` },
  { at: 9, name: 'replan', where: 'in the turn', say: () => 'Step back: write a short new plan for this step before you do anything else.' },
  { at: 12, name: 'think_harder', where: 'between turns', say: () => 'Re-run the step one effort level higher: medium -> high.' },
  { at: 15, name: 'fresh_start', where: 'between turns', say: () => 'Checkpoint, end the session, start a new one from notes.md.' },
  { at: 18, name: 'ask_person', where: 'between turns', say: (v) => `Ask in the ticket's thread: "I'm stuck: ${v.loopKind ?? 'no progress'}. What should I try?"` },
];

export const rungFor = (verdict) => RUNGS.find((r) => r.at === verdict.flatFor);
