// Feeds one recorded run to the watcher and prints what the ladder would do.   node run.mjs flaky
import { SEQUENCES } from './events.mjs';
import { rungFor } from './ladder.mjs';
import { Watcher } from './watcher.mjs';

const name = process.argv[2] ?? 'healthy';
const watcher = new Watcher();
console.log(` #  event                                   flat  loop`);
SEQUENCES[name].forEach((raw, i) => {
  const v = watcher.onTool(raw);
  const what = `${raw.tool} ${raw.input}${raw.passed === true ? ' (pass)' : raw.passed === false ? ' (fail)' : ''}`;
  console.log(`${String(i + 1).padStart(2)}  ${what.padEnd(40)} ${String(v.flatFor).padStart(4)}  ${v.loopKind ?? '-'}`);
  const rung = rungFor(v);
  if (rung) console.log(`    -> rung ${rung.name} (${rung.where}): ${rung.say(v)}`);
});
